package workbench.kotlin.l05

/*
 * Do not edit this file. It is the same in src/main and src/solution.
 * ensure is inline, so a test that called it directly would keep a copy of the stub. The tests call
 * this ordinary function instead; it is compiled with your code and holds a fresh copy of ensure.
 */
object Callers {
    fun ensuring(condition: Boolean, code: String, lazyMessage: () -> String) = ensure(condition, code, lazyMessage)
}
